INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (101, 0, 160, 105, "仲間と夏を楽しむ、夏海の魔法士。自分を変えたいという固い決意で、障害物を無効化して走り続ける。", 122601, 1, 1, 0, 1, 110, 1.5, 1, 0.029);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (102, 0, 120, 111, "太陽よりも輝く、夏海の元気娘。　持ち前の身体能力で、どんなコースも柔軟に対応し、駆け抜ける。", 122401, 2, 0, 1, 2, 105, 2.5, 3, 0.014);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (103, 1, 350, 105, "波打ち際に煌めく、夏海の剣士。　日々の鍛錬で鍛えた脚で、長い距離も速度を落とさず走り切る。", 122501, 3, 0, 0, 3, 110, 2.5, 2, 0.017);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (104, 0, 130, 105, "海の幸に目がない、渚のお姫様。　『王家の装備』の力を解放し、障害物をものともせず前へと進む。", 107501, 4, 0, 1, 4, 110, 1.5, 3, 0.016);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (105, 0, 160, 105, "海でも主さまをお世話する、白浜の巫女。精霊の力で自身を加速させ、誰よりも速くゴールを目指す。", 107601, 5, 1, 0, 5, 110, 2.5, 1, 0.014);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (106, 1, 255, 103, "水着姿を恥じらう、ツンデレ猫娘。お得意の魔法で、対戦相手の走りを妨害し、レースを有利に進める。", 107801, 6, 0, 0, 6, 120, 3.5, 2, 0.029);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (107, 0, 160, 103, "優雅に浜を駆ける、真夏のマホ姫。しゃなりしゃなりと、雅な身のこなしで障害物を跳び越えていく。", 110601, 7, 1, 0, 7, 120, 3.5, 1, 0.013);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (108, 1, 350, 103, "浜の平和を守る、真夏の狼娘。　　獣人の強靭なスタミナで、レース　後半にスパートをかける。", 110401, 8, 0, 0, 8, 110, 2.5, 2, 0.014);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (109, 0, 130, 100, "浜に力強く舞う、真夏の南国娘。　レースの喧噪の中でも精神を乱さず後半に大きな捲りを見せる。", 110501, 9, 0, 1, 9, 105, 1.5, 3, 0.012);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (110, 0, 200, 103, "浜の事件を嗅ぎ付けた、真夏の　　名探偵。高い推理力と魔法で、的確に対戦相手の走りを乱す。", 115701, 10, 1, 0, 10, 105, 2.5, 1, 0.014);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (111, 1, 350, 103, "再び鎧を脱いだ、灼熱の騎士団長。実戦で培った判断力で、瞬時にバリアを展開し、障害物を無力化する。", 113601, 11, 0, 0, 11, 105, 2.5, 2, 0.071);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (112, 0, 130, 103, "水が苦手な、海辺の気まぐれ猫娘。浜に現れた美少女義賊は、対戦相手のスピードを奪いとる。", 107901, 12, 0, 1, 12, 120, 1.5, 3, 0.014);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (113, 0, 200, 105, "バカンスも効率第一な、海の傭兵。レースでも最高効率を求め、どんな状況でも隙のない走りを見せる。", 108001, 13, 1, 0, 13, 110, 1.5, 2, 0.022);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (114, 0, 160, 108, "真夏の太陽が良く似合う、海辺の　サレンママ。多才で器用、どんな　障害物もエレガントに越えていく。", 110301, 14, 1, 0, 14, 110, 2.5, 1, 0.031);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (115, 0, 130, 105, "海に嵐を呼ぶ夏のドジっ娘メイド。日頃から災難に慣れており、多少　のトラブルには動じたりしない。", 107701, 15, 0, 1, 15, 110, 0.5, 1, 0.036);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (116, 1, 350, 95, "粋な夏を愉しむ、若夏の姉御。　　流麗な身体捌きで、始・継・終と、UBを重ねるごとに、加速する。", 113101, 16, 0, 0, 16, 110, 3.5, 2, 0.048);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (117, 0, 130, 105, "夏のトキメキに触れた、オタク魔法少女。多彩な魔法を操り、少しずつ他の走者の速度を落とし続ける。", 113301, 17, 0, 1, 17, 105, 1.5, 3, 0.043);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (118, 0, 130, 95, "海獄に降臨せし、真夏の冥姫。　　レース後半に魔力を全解放し、　　蒼き疾風と成りて浜を駆け抜ける。", 113201, 18, 0, 1, 18, 105, 1.5, 2, 0.018);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (119, 0, 160, 108, "夏の夕を火花で彩る、渚の壊し屋。『壊し屋』の異名と過激な愛情は、対戦相手にプレッシャーを与える。", 117001, 19, 1, 0, 19, 110, 2.5, 2, 0.021);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (120, 1, 255, 105, "青春に生きる者を導く、夏の先生。夢へと邁進する聖母の加護が、その身をあらゆる困難から守る。", 113501, 20, 0, 0, 20, 110, 2.5, 1, 0.036);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (121, 1, 350, 105, "笑顔の応援が眩しい、夏の超能力　ガール。超能力を駆使して、どんな障害物もひとっ飛びで乗り越える。", 113401, 21, 0, 0, 21, 105, 2.5, 3, 0.02);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (122, 0, 130, 105, "海辺で大人の魅力を放つ、夏の　　セクシー先生。その魅力に囚われた対戦相手は、走りを乱してしまう。", 110101, 22, 0, 1, 22, 110, 2.5, 1, 0.018);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (123, 0, 160, 111, "水着も絶対外さない、夏のカリスマモデル。走りのバイブスは超テンアゲで、スピードはおにやば。", 110001, 23, 1, 0, 23, 105, 3.5, 3, 0.03);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (124, 0, 130, 103, "南の島も盛り上げる、真夏のアイドル。悪天候でも笑顔を絶やさず後半もリズムを上げて走り切る。", 117201, 24, 0, 1, 24, 110, 1.5, 1, 0.027);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (125, 0, 160, 108, "海原に美声を響かす、渚の歌姫。　守護の賛歌と精霊の加護により、　障害物から身を守る。", 117301, 25, 1, 0, 25, 105, 3.5, 2, 0.02);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (126, 1, 350, 105, "夏でも天邪鬼な、夕凪のテーラー。張り巡らされた魔法の糸で、他の走者の自由を奪う。", 117401, 26, 0, 0, 26, 110, 2.5, 3, 0.04);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (127, 1, 350, 105, "向日葵が良く似合う、海辺の　　　お姉ちゃん。秘密結社の一員で、　抜群の身体能力が一番の武器。", 117101, 27, 0, 0, 27, 110, 3.5, 1, 0.009);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (128, 1, 255, 105, "渚でおっとり、夏色うさぎっこ。　うさぎさんパワー全開で、ぴょん　ぴょんとコースを跳ね回る。", 122901, 28, 0, 0, 28, 120, 3.5, 1, 0.022);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (129, 0, 130, 105, "無邪気さ弾ける、夏色いたずら娘。砂浜でも、いたずらの準備は万端！レースに大波乱が巻き起こる！？", 122801, 29, 0, 1, 29, 110, 2.5, 3, 0.028);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (130, 0, 130, 108, "海でも真面目な、夏色優等生。　　高めた魔力を解き放ち、一瞬の内に他の走者を置き去りにする。", 122701, 30, 1, 0, 30, 105, 3.5, 2, 0.023);
